@pytest.mark.parametrize("ref_lat,ref_lon,heading,x,z,lat,lon", SWIFT_FORWARD)
def test_forward_matches_swift(ref_lat, ref_lon, heading, x, z, lat, lon):
    got_lat, got_lon = LocalProjection(ref_lat, ref_lon, heading).coordinate(x, z)
    assert got_lat == pytest.approx(lat, abs=1e-11)
    assert got_lon == pytest.approx(lon, abs=1e-11)


@pytest.mark.parametrize("ref_lat,ref_lon,heading,lat,lon,x,z", SWIFT_INVERSE)
def test_inverse_matches_swift(ref_lat, ref_lon, heading, lat, lon, x, z):
    got_x, got_z = LocalProjection(ref_lat, ref_lon, heading).map_point(lat, lon)
    assert got_x == pytest.approx(x, abs=1e-5)
    assert got_z == pytest.approx(z, abs=1e-5)


def _meters(reference: LocalProjection, lat: float, lon: float) -> np.ndarray:
    """Independent measurement in the renderers' projected space (Swift test helper)."""
    scale = math.cos(math.radians(reference.latitude))
    delta = (lon - reference.longitude + 180) % 360 - 180
    east = math.radians(delta) * EARTH_RADIUS_M * scale
    north = EARTH_RADIUS_M * math.log(math.tan(math.pi / 4 + math.radians(lat) / 2)
                                      / math.tan(math.pi / 4 + math.radians(reference.latitude) / 2)) * scale
    return np.array([east, north])


def test_heading_uses_local_negative_z_as_north():
    north_facing = LocalProjection(0, 0)
    assert np.allclose(_meters(north_facing, *north_facing.coordinate(0, -10)), [0, 10], atol=1e-7)
    assert np.allclose(_meters(north_facing, *north_facing.coordinate(10, 0)), [10, 0], atol=1e-7)
    east_facing = LocalProjection(0, 0, 90)
    assert np.allclose(_meters(east_facing, *east_facing.coordinate(0, -10)), [10, 0], atol=1e-7)
    assert np.allclose(_meters(east_facing, *east_facing.coordinate(10, 0)), [0, -10], atol=1e-7)


@pytest.mark.parametrize("latitude", [0.0, 37.3, 60.0, -60.0])
def test_projection_preserves_meters(latitude):
    reference = LocalProjection(latitude, 12)
    lat, lon = reference.coordinate(30, -40)
    assert np.allclose(_meters(reference, lat, lon), [30, 40], atol=1e-6)
    expected = 30 / (EARTH_RADIUS_M * math.cos(math.radians(latitude))) / (math.pi / 180)
    assert lon - 12 == pytest.approx(expected, abs=1e-10)


def test_vectorised_round_trip_without_changing_the_local_frame():
    points = np.array([[0, 0], [31.2, -19.7], [-102.8, 210.6], [1e-3, -1e-3]])
    for heading in [0.0, 90, -45, 360, 725.5]:
        reference = LocalProjection(51.5, -0.1, heading)
        assert np.allclose(reference.to_local(reference.to_lonlat(points)), points, atol=1e-6)
        assert reference.to_lonlat(points[1]).shape == (2,)


def test_dateline_stays_local():
    for longitude in (179.99999, -179.99999):
        reference = LocalProjection(25, longitude)
        point = (20 if longitude > 0 else -20, -3)
        lat, lon = reference.coordinate(*point)
        assert lon * longitude < 0 and abs(lon) < 180
        assert np.allclose(reference.map_point(lat, lon), point, atol=1e-6)


def test_offset_m_is_east_north():
    lat, lon = LocalProjection(33.0, -84.0, 0).coordinate(3, -4)     # 3 m east, 4 m north
    assert np.allclose(offset_m(33.0, -84.0, lat, lon), [[3, 4]], atol=1e-9)


def test_wrap_degrees_matches_swift():
    assert wrap_degrees(180) == -180 and wrap_degrees(-180) == -180
    assert wrap_degrees(540) == -180 and wrap_degrees(-190) == 170 and wrap_degrees(725.5) == 5.5


@pytest.mark.parametrize("reference", [
    LocalProjection(math.nan, 0), LocalProjection(85.05112878, 0), LocalProjection(-90, 0),
    LocalProjection(0, math.inf), LocalProjection(0, 181), LocalProjection(0, 0, math.nan),
    LocalProjection(0, 0, 0, -1), LocalProjection(0, 0, 0, math.inf),
])
def test_rejects_invalid_references(reference):
    with pytest.raises(GeoError):
        reference.validate()


def test_rejects_invalid_points_and_out_of_coverage():
    reference = LocalProjection(0, 0)
    with pytest.raises(GeoError):
        reference.coordinate(math.nan, 0)
    with pytest.raises(GeoError):
        reference.coordinate(0, -1.7e308)
    with pytest.raises(GeoError):
        reference.map_point(90, 0)
    with pytest.raises(GeoError):
        LocalProjection(85.05, 0).coordinate(0, -1000)
